'use strict';

// MODULES //

var join = require( '@stdlib/array/base/join' );
var trim = require( '@stdlib/string/trim' );
var replace = require( '@stdlib/string/replace' );


// FUNCTIONS //

/**
* Appends the plain-text representation of an MDAST node.
*
* @private
* @param {Object} node - MDAST node
* @param {Array} out - output array
* @returns {void}
*/
function append( node, out ) {
	var i;

	// Text and code contribute their literal value. Formatting nodes are ignored, because this projection is used for classification rather than rendering...
	if ( node.type === 'text' || node.type === 'inlineCode' || node.type === 'code' ) {
		out.push( node.value );
		return;
	}
	if ( node.type === 'image' || node.type === 'imageReference' ) {
		// Alternative text is the textual meaning of an image when available...
		if ( node.alt ) {
			out.push( node.alt );
		}
		return;
	}
	if ( node.type === 'break' || node.type === 'thematicBreak' ) {
		out.push( ' ' );
		return;
	}
	if ( node.children ) {
		// Traverse unknown containers rather than maintaining a closed MDAST type list. Block-level boundaries append whitespace to prevent word merging...
		for ( i = 0; i < node.children.length; i++ ) {
			append( node.children[ i ], out );
		}
		if ( node.type === 'paragraph' || node.type === 'heading' || node.type === 'listItem' || node.type === 'blockquote' ) {
			out.push( ' ' );
		}
	}
}


// MAIN //

/**
* Returns the normalized plain-text representation of an MDAST node.
*
* @private
* @param {Object} node - MDAST node
* @returns {string} plain text
*/
function plainText( node ) {
	var out = [];

	append( node, out );

	// Collapse structural whitespace so heading and role classification receives a stable value regardless of Markdown wrapping or nested inline formatting:
	return trim( replace( join( out, '' ), /\s+/g, ' ' ) );
}


// EXPORTS //

module.exports = plainText;
